def minBusRoutes(routes, source, target):
    if source == target:
        return 0
    lines_at = {}
    for i, route in enumerate(routes):
        for s in route:
            lines_at.setdefault(s, []).append(i)
    if source not in lines_at or target not in lines_at:
        return -1
    used = [False] * len(routes)
    seen = {source}
    level = [source]
    rides = 0
    while level:
        rides += 1
        nxt = []
        for s in level:
            for i in lines_at[s]:
                if used[i]:
                    continue
                used[i] = True
                for t in routes[i]:
                    if t == target:
                        return rides
                    if t not in seen:
                        seen.add(t)
                        nxt.append(t)
        level = nxt
    return -1
